using System;
using System.IO;
using System.Security.Cryptography;

namespace Shaiya_Duff_Updater
{
    // SAFB sidecar format (48 bytes):
    //   [0-3]   "SAFB"                 magic
    //   [4-7]   1u                     version (uint32 LE)
    //   [8-39]  HMAC-SHA256(sah, key)  32 bytes
    //   [40-47] plainSah.Length        uint64 LE (cross-check)
    //
    // Key = SahKeyHex (same key used to encrypt data.sah as ESAH).
    // Generated by Updater; verified by sdev-client.dll before game.exe loads the VFS.
    public static class SafbSidecar
    {
        private const int SidecarSize = 48;

        public static void Write(string safbPath, byte[] plainSah, byte[] key)
        {
            using (var hmac = new HMACSHA256(key))
            {
                byte[] mac = hmac.ComputeHash(plainSah);
                byte[] buf = new byte[SidecarSize];
                buf[0] = (byte)'S'; buf[1] = (byte)'A'; buf[2] = (byte)'F'; buf[3] = (byte)'B';
                WriteUInt32(buf, 4, 1u);
                Buffer.BlockCopy(mac, 0, buf, 8, 32);
                WriteUInt64(buf, 40, (ulong)plainSah.Length);
                File.WriteAllBytes(safbPath, buf);
            }
        }

        // Regenerate data.safb from the current data.sah using the supplied key hex.
        // Always overwrites. Call after every SAH patch and before game launch.
        public static void Regenerate(string dataSahPath, string sahKeyHex, string safbPath)
        {
            if (string.IsNullOrWhiteSpace(sahKeyHex)) return;
            byte[] key = ParseHexKey(sahKeyHex);
            if (key == null) return;
            byte[] plainSah = ReadPlainSah(dataSahPath, key);
            if (plainSah == null) return;
            try
            {
                Write(safbPath, plainSah, key);
                AppLogger.Patch("SAFB sidecar written: " + Path.GetFileName(safbPath));
            }
            catch (Exception ex)
            {
                AppLogger.PatchError("SAFB sidecar write failed", ex);
            }
        }

        // Generate data.safb only if missing (first-install guard).
        public static void EnsureExists(string dataSahPath, string sahKeyHex, string safbPath)
        {
            if (!File.Exists(safbPath))
                Regenerate(dataSahPath, sahKeyHex, safbPath);
        }

        private static byte[] ReadPlainSah(string path, byte[] key)
        {
            if (!File.Exists(path)) return null;
            byte[] data;
            try { data = File.ReadAllBytes(path); }
            catch { return null; }
            if (data.Length >= 3 && data[0] == 'S' && data[1] == 'A' && data[2] == 'H')
                return data;
            if (data.Length >= 4 && data[0] == 'E' && data[1] == 'S' && data[2] == 'A' && data[3] == 'H')
            {
                try { return SahCrypt.DecryptBuffer(data, key); }
                catch { return null; }
            }
            return null;
        }

        private static byte[] ParseHexKey(string hex)
        {
            if (string.IsNullOrWhiteSpace(hex)) return null;
            string clean = hex.Replace(" ", "").Replace("-", "");
            if (clean.Length != 64) return null;
            try
            {
                byte[] key = new byte[32];
                for (int i = 0; i < 32; i++)
                    key[i] = Convert.ToByte(clean.Substring(i * 2, 2), 16);
                return key;
            }
            catch { return null; }
        }

        private static void WriteUInt32(byte[] buf, int off, uint v)
        {
            buf[off]     = (byte)v;
            buf[off + 1] = (byte)(v >> 8);
            buf[off + 2] = (byte)(v >> 16);
            buf[off + 3] = (byte)(v >> 24);
        }

        private static void WriteUInt64(byte[] buf, int off, ulong v)
        {
            for (int i = 0; i < 8; i++) buf[off + i] = (byte)(v >> (8 * i));
        }
    }
}
